const art=$('#art'),stage=art.parentElement,memory=document.createElement('canvas');memory.width=360;memory.height=240;memory.style.cssText='position:absolute;inset:0;width:100%;height:100%;image-rendering:pixelated';memory.setAttribute('aria-hidden','true');stage.prepend(memory);const paint=memory.getContext('2d');let artMode='space',gl=null,programs={},artReady=false,artVisible=true,artTime=0,artLast=0,paintLast=0,aim={x:0,y:0};
function polygon(points,fill){paint.fillStyle=fill;paint.beginPath();points.forEach((p,i)=>i?paint.lineTo(...p):paint.moveTo(...p));paint.closePath();paint.fill()}function cube(x,y,w,d,h){polygon([[x,y],[x+w,y-d],[x+w+d,y],[x+d,y+d]],'#8a7b9f');polygon([[x,y],[x+d,y+d],[x+d,y+d+h],[x,y+h]],'#554665');polygon([[x+d,y+d],[x+w+d,y],[x+w+d,y+h],[x+d,y+d+h]],'#3a304a')}
function memoryScene(){paint.fillStyle='#211b2c';paint.fillRect(0,0,360,240);paint.strokeStyle='#4c3e5a66';paint.lineWidth=.6;for(let i=-4;i<12;i++){paint.beginPath();paint.moveTo(0,i*27);paint.lineTo(360,i*27+90);paint.stroke()}cube(70,67,130,35,120);cube(20,159,70,25,60);cube(120,150,108,40,65);cube(258,155,61,21,62);for(let i=0;i<5;i++){paint.fillStyle=i%2?'#76638d':'#9884a8';paint.fillRect(84+i*13,122-i*6,40,5)}let bob=Math.sin(artTime*2)*5;polygon([[255,43+bob],[268,30+bob],[280,47+bob],[266,64+bob]],'#8971a7');polygon([[255,43+bob],[268,30+bob],[267,48+bob]],'#b49acb');paint.fillStyle='#c7afd5';paint.font='7px monospace';paint.fillText('MEMORY_008 / CONNECTED',12,222)}
function compile(type,src){const s=gl.createShader(type);gl.shaderSource(s,src);gl.compileShader(s);if(!gl.getShaderParameter(s,gl.COMPILE_STATUS))return null;return s}function link(vert,frag){const vs=compile(gl.VERTEX_SHADER,vert),fs=compile(gl.FRAGMENT_SHADER,frag);if(!vs||!fs)return null;let p=gl.createProgram();gl.attachShader(p,vs);gl.attachShader(p,fs);gl.linkProgram(p);gl.deleteShader(vs);gl.deleteShader(fs);if(!gl.getProgramParameter(p,gl.LINK_STATUS))return null;let u={};for(let i=0;i<gl.getProgramParameter(p,gl.ACTIVE_UNIFORMS);i++){let n=gl.getActiveUniform(p,i).name;u[n]=gl.getUniformLocation(p,n)}return{p,u}}
function initArt(){gl=art.getContext('webgl2',{alpha:true,antialias:false,powerPreference:'low-power'});if(!gl)return false;programs.prism=link(OFFShaders.Prism.vertex,OFFShaders.Prism.fragment);programs.chrome=link(OFFShaders.LiquidChrome.vertex,OFFShaders.LiquidChrome.fragment);if(!programs.prism||!programs.chrome)return false;gl.bindVertexArray(gl.createVertexArray());const tex=gl.createTexture();gl.bindTexture(gl.TEXTURE_2D,tex);gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA,1,1,0,gl.RGBA,gl.UNSIGNED_BYTE,new Uint8Array([0,0,0,255]));gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MIN_FILTER,gl.LINEAR);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MAG_FILTER,gl.LINEAR);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_S,gl.CLAMP_TO_EDGE);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_T,gl.CLAMP_TO_EDGE);return true}
function rotation(y,p,r){let cy=Math.cos(y),sy=Math.sin(y),cx=Math.cos(p),sx=Math.sin(p),cz=Math.cos(r),sz=Math.sin(r);return[cy*cz+sy*sx*sz,cx*sz,-sy*cz+cy*sx*sz,-cy*sz+sy*sx*cz,cx*cz,sy*sz+cy*sx*cz,sy*cx,-sx,cy*cx]}
function drawShader(){if(!artReady||artMode==='space')return;const{p,u}=programs[artMode];gl.useProgram(p);gl.viewport(0,0,art.width,art.height);gl.clearColor(.08,.06,.11,1);gl.clear(gl.COLOR_BUFFER_BIT);gl.uniform2f(u.uResolution,art.width,art.height);gl.uniform1f(u.uTime,artTime);if(artMode==='prism'){gl.uniformMatrix3fv(u.uRay,false,rotation(artTime*.3+aim.x*.2,.5,.15));gl.uniform1f(u.uGlow,1.5);gl.uniform2f(u.uOffset,0,-8);gl.uniform1f(u.uColorFreq,1.1);gl.uniform1f(u.uCenterShift,.88);gl.uniform1f(u.uInvBaseHalf,1/2.75);gl.uniform1f(u.uInvHeight,1/3.5);gl.uniform1f(u.uMinAxis,2.75);gl.uniform1f(u.uPxScale,1/(art.height*.1*2));gl.uniform1i(u.uUsePalette,0);gl.uniform1i(u.uPalette,0);gl.uniform1f(u.uNoise,.025);gl.uniform1f(u.uSaturation,.6);gl.uniformMatrix3fv(u.uHue,false,[.7,.03,.14,.08,.38,.15,.16,.06,.94]);gl.uniform1i(u.uUseHue,1);gl.uniform1f(u.uLight,0);gl.uniform1f(u.uNeutral,0)}else{gl.uniform1f(u.uUnit,240);gl.uniform1f(u.uAmplitude,.43);gl.uniform2f(u.uFrequency,2.7,2.4);gl.uniform1f(u.uDetail,4);gl.uniform1f(u.uSharpness,1.15);gl.uniform1f(u.uDepth,.85);gl.uniform1f(u.uPresence,1);gl.uniform3fv(u.uTint,[.27,.19,.58]);gl.uniform2f(u.uShift,aim.x*.2,aim.y*.2);gl.uniform1f(u.uRoughness,.43);gl.uniform1f(u.uExposure,.68);gl.uniform1f(u.uLight,0);gl.uniform1i(u.uSlope,0);gl.uniform2f(u.uSlopeSize,1,1);gl.uniform1f(u.uRipple,0)}gl.drawArrays(gl.TRIANGLES,0,3)}
function artSwitch(mode){if(mode!=='space'&&!artReady){toast('此设备不支持金属渲染，保留记忆空间');return}artMode=mode;memory.hidden=mode!=='space';art.hidden=mode==='space';document.querySelectorAll('[data-art]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.art===mode));if(mode==='space')memoryScene();else drawShader();if(!motionPaused&&!reduced.matches)stage.animate([{opacity:.45},{opacity:1}],{duration:550})}artReady=initArt();memoryScene();art.hidden=true;document.querySelectorAll('[data-art]').forEach(b=>b.onclick=()=>artSwitch(b.dataset.art));stage.addEventListener('pointermove',ev=>{const r=stage.getBoundingClientRect();aim.x=(ev.clientX-r.left)/r.width*2-1;aim.y=(ev.clientY-r.top)/r.height*2-1});stage.addEventListener('pointerleave',()=>aim={x:0,y:0});stage.addEventListener('click',ev=>{if(motionPaused||reduced.matches)return;$('#art-figure').animate([{transform:'translateY(0)'},{transform:'translateY(-10px)'},{transform:'translateY(0)'}],{duration:750,easing:'ease-in-out'});artTime+=.1});new IntersectionObserver(entries=>artVisible=entries[0].isIntersecting).observe(stage);function artFrame(now){let dt=Math.min((now-artLast)/1000||0,.05);artLast=now;if(artVisible&&!document.hidden&&!document.body.classList.contains('room-open')&&!motionPaused&&!reduced.matches){artTime+=dt*.3;if(now-paintLast>33){paintLast=now;if(artMode==='space')memoryScene();else drawShader()}}requestAnimationFrame(artFrame)}requestAnimationFrame(artFrame);art.addEventListener('webglcontextlost',ev=>{ev.preventDefault();artReady=false;artSwitch('space')});art.addEventListener('webglcontextrestored',()=>{artReady=initArt();artSwitch('space')});
const backgroundHost=document.createElement('div');backgroundHost.className='ambient-site-background';backgroundHost.setAttribute('aria-hidden','true');document.body.prepend(backgroundHost);backgroundHost.append(stage);art.width=720;art.height=480;artVisible=true;window.mountRouteArt=()=>{backgroundHost.append(stage);stage.classList.add('background-art');stage.hidden=false;artSwitch(['home','guides','wiki'].includes(route.split('/')[0])?'prism':'chrome')};window.mountRouteArt();
